package com.ge.apm.dao;import com.ge.apm.domain.V2_WorkOrder_Detail;import org.springframework.data.jpa.repository.Modifying;import webapp.framework.dao.GenericRepositoryUUID;import org.springframework.data.jpa.repository.Query;import webapp.framework.dao.GenericRepositoryUUID;import java.util.List;/** * Created by lsg on 8/8/2017. */public interface WorkOrderDetailRepository extends GenericRepositoryUUID<V2_WorkOrder_Detail> {    public List<V2_WorkOrder_Detail> getByWoIdOrderByCreatedDateAsc(String woId);    public List<V2_WorkOrder_Detail> getByWoIdOrderByCreatedDateDesc(String woId);    public List<V2_WorkOrder_Detail> findByWoId(String woId);    @Modifying    @Query(value ="delete from V2_WorkOrder_Detail where id = ?1")    public void deleteById(String id);}